const KEY='salah-soft-depth-v1';
export function depthEnabled(){try{return localStorage.getItem(KEY)!=='off'}catch{return false}}
export function initSoftDepth(){document.documentElement.classList.toggle('soft-depth',depthEnabled())}
export function mountSoftDepthSetting(root){const groups=root.querySelector('.settings-grid');if(!groups||root.querySelector('#soft-depth'))return;const section=document.createElement('details');section.className='panel settings-group';section.innerHTML='<summary><span class="settings-label">Оформление</span></summary><div class="settings-group-body"><label class="switch-row" for="soft-depth"><span>Объёмное оформление</span><input id="soft-depth" type="checkbox"></label><p class="muted">Мягкие тени и тонкие блики. Выключите, чтобы вернуть прежний плоский вид.</p><p class="muted" id="soft-depth-status" role="status" hidden></p></div>';const atmosphere=[...groups.querySelectorAll('.settings-group')].find(group=>group.querySelector('summary')?.textContent.includes('Оформление и атмосфера'));const body=atmosphere?.querySelector('.settings-group-body');if(body){const content=section.querySelector('.settings-group-body');body.prepend(...content.childNodes)}else groups.prepend(section);const input=root.querySelector('#soft-depth');input.checked=depthEnabled();input.onchange=()=>{const before=depthEnabled();try{localStorage.setItem(KEY,input.checked?'on':'off');initSoftDepth()}catch{input.checked=before;const status=root.querySelector('#soft-depth-status');status.hidden=false;status.textContent='Не удалось сохранить оформление. Попробуйте ещё раз.'}}}
window.addEventListener('storage',event=>{if(event.key===KEY){initSoftDepth();const input=document.getElementById('soft-depth');if(input)input.checked=depthEnabled()}});
